import { describe, it, expect } from 'vitest';
import { applyElkLayoutX6 } from './layout';
import { CARD_WIDTH, CARD_HEADER_H } from '../model/geometry';

type Node = { id: string, x: number, y: number, data?: any, width?: number, height?: number };
type Edge = { id: string, source: { cell: string }, target: { cell: string } };

describe('applyElkLayout', () => {
  it('returns an empty result when given no nodes', async () => {
    const result = await applyElkLayoutX6([], []);
    expect(result).toEqual({ nodes: [], edges: [] });
  });

  it('positions connected nodes differently from (0,0) with rightward flow', async () => {
    const nodes: Node[] = [
      {
        id: 'node-1',
        x: 0, y: 0,
        data: { label: 'Source' },
        width: CARD_WIDTH,
        height: CARD_HEADER_H,
      },
      {
        id: 'node-2',
        x: 0, y: 0,
        data: { label: 'Target' },
        width: CARD_WIDTH,
        height: CARD_HEADER_H,
      },
    ];

    const edges: Edge[] = [
      {
        id: 'edge-1-2',
        source: { cell: 'node-1' },
        target: { cell: 'node-2' },
      },
    ];

    const layoutedNodes = (await applyElkLayoutX6(nodes, edges)).nodes;

    expect(layoutedNodes).toHaveLength(2);

    const n1 = layoutedNodes.find((n) => n.id === 'node-1');
    const n2 = layoutedNodes.find((n) => n.id === 'node-2');

    expect(n1).toBeDefined();
    expect(n2).toBeDefined();

    // Verify positions changed from 0,0
    expect(n1!.x !== 0 || n1!.y !== 0).toBe(true);
    expect(n2!.x !== 0 || n2!.y !== 0).toBe(true);

    // Direction is RIGHT: target node must be positioned to the right of source node
    expect(n2!.x).toBeGreaterThan(n1!.x + CARD_WIDTH);

    // Verify preservation of node data and dimensions
    expect(n1!.data).toEqual({ label: 'Source' });
    expect(n2!.data).toEqual({ label: 'Target' });
    expect(n1!.width).toBe(CARD_WIDTH);
    expect(n1!.height).toBe(CARD_HEADER_H);
  });

  it('lays out multi-node branch structures with distinct coordinates', async () => {
    const nodes: Node[] = [
      {
        id: 'src',
        x: 0, y: 0,
        data: {},
        width: 200,
        height: 100,
      },
      {
        id: 'dst1',
        x: 0, y: 0,
        data: {},
        width: 200,
        height: 100,
      },
      {
        id: 'dst2',
        x: 0, y: 0,
        data: {},
        width: 200,
        height: 100,
      },
    ];

    const edges: Edge[] = [
      { id: 'e1', source: { cell: 'src' }, target: { cell: 'dst1' } },
      { id: 'e2', source: { cell: 'src' }, target: { cell: 'dst2' } },
    ];

    const layouted = (await applyElkLayoutX6(nodes, edges)).nodes;
    const src = layouted.find((n) => n.id === 'src')!;
    const dst1 = layouted.find((n) => n.id === 'dst1')!;
    const dst2 = layouted.find((n) => n.id === 'dst2')!;

    // Both destination nodes should be to the right of source
    expect(dst1.x).toBeGreaterThan(src.x);
    expect(dst2.x).toBeGreaterThan(src.x);

    // Destination nodes in the same layer should have different vertical positions
    expect(dst1.y).not.toBe(dst2.y);
  });
});

import ELK from 'elkjs/lib/elk.bundled.js';
import type { ElkNode, ElkExtendedEdge } from 'elkjs';
import { CARD_WIDTH, CARD_HEADER_H } from '../model/geometry';

const elk = new ELK();

export interface ElkLayoutOptions {
  wireSpacing?: number;
  portPadding?: number;
}

export async function applyElkLayoutX6(
  nodes: any[],
  edges: any[],
  options: { wireSpacing?: number; portPadding?: number } = {}
): Promise<{ nodes: any[]; edges: any[] }> {
  if (nodes.length === 0) return { nodes, edges };

  const wSpacing = (options?.wireSpacing ?? 10).toString();
  const pPadding = (options?.portPadding ?? 30).toString(); // User requested 30px minimum straight out of terminal

  const elkNodes: ElkNode[] = nodes.map((node) => {
    return {
      id: node.id,
      width: node.width ?? CARD_WIDTH,
      height: node.height ?? CARD_HEADER_H,
      layoutOptions: {
        'elk.portConstraints': 'FIXED_POS'
      },
      ports: node.ports?.items?.map((p: any) => ({
        id: p.id,
        x: p.args?.x ?? (p.group === 'in' ? 0 : (node.width ?? CARD_WIDTH)),
        y: p.args?.y ?? 0,
        properties: { 
          'port.side': p.group === 'in' ? 'WEST' : 'EAST'
        }
      })) || []
    };
  });

  const elkEdges: ElkExtendedEdge[] = edges.map((edge) => ({
    id: edge.id,
    sources: [edge.source.port || edge.source.cell],
    targets: [edge.target.port || edge.target.cell],
  }));

  const graph: ElkNode = {
    id: 'root',
    layoutOptions: {
      'elk.algorithm': 'layered',
      'elk.direction': 'RIGHT',
      'elk.layered.spacing.nodeNodeBetweenLayers': '150',
      'elk.layered.spacing.edgeNodeBetweenLayers': pPadding, // This forces the edge to go straight for pPadding pixels
      'elk.spacing.edgeEdge': wSpacing,
      'elk.spacing.nodeNode': '80',
      'elk.edgeRouting': 'ORTHOGONAL',
      'elk.layered.nodePlacement.strategy': 'NETWORK_SIMPLEX'
    },
    children: elkNodes,
    edges: elkEdges,
  };

  const layoutedGraph = await elk.layout(graph);
  const positionMap = new Map<string, { x: number; y: number }>();
  const edgePositionMap = new Map<string, Array<{ x: number; y: number }>>();

  for (const child of layoutedGraph.children ?? []) {
    if (child?.x !== undefined && child?.y !== undefined) {
      positionMap.set(child.id, { x: child.x, y: child.y });
    }
  }

  for (const edge of layoutedGraph.edges ?? []) {
    if (edge?.sections && edge.sections.length > 0) {
      const bends = edge!.sections![0]!.bendPoints ?? [];

      const allPoints = [];
      if (edge!.sections![0]!.startPoint) allPoints.push(edge!.sections![0]!.startPoint);
      allPoints.push(...bends);
      if (edge!.sections![0]!.endPoint) allPoints.push(edge!.sections![0]!.endPoint);

      edgePositionMap.set(edge.id, allPoints.map((b: any) => ({ x: b.x, y: b.y })));
    }
  }

  const updatedNodes = nodes.map((node) => {
    const pos = positionMap.get(node.id);
    if (!pos) return node;
    return {
      ...node,
      x: pos.x,
      y: pos.y,
    };
  });

  const updatedEdges = edges.map((edge) => {
    const bends = edgePositionMap.get(edge.id);
    if (!bends || bends.length === 0) return edge;
    return {
      ...edge,
      vertices: bends
    };
  });

  return { nodes: updatedNodes, edges: updatedEdges };
}

