function NavItem({ to, label, activePattern }: { to: string; label: string; activePattern?: string | RegExp }) {
  const location = useLocation();
  let isActive = location.pathname === to;
  if (activePattern) {
    if (typeof activePattern === 'string') {
      isActive = location.pathname.startsWith(activePattern);
    } else {
      isActive = activePattern.test(location.pathname);
    }
  }
  return (
    <li>
      <Link to={to} className={isActive ? 'active' : ''}>
        {label}
      </Link>
    </li>
  );
}

