import { describe, it, expect, vi } from 'vitest';
import { useDocumentStore } from './documentStore';
import { bffClient } from '../api/client';

describe('documentStore', () => {
  it('saveDocument calls authorTopology', async () => {
    const mockDoc = {
      schemaVersion: 1 as const,
      designLabel: 'v1',
      revision: '1',
      sites: [],
      locations: [],
      racks: [],
      deviceTypes: [],
      devices: [],
      cables: [],
      signalClasses: [], zones: []
    };
    
    useDocumentStore.getState().loadDocument(mockDoc);
    
    const authorTopologySpy = vi.spyOn(bffClient, 'authorTopology').mockResolvedValue(undefined);
    
    await useDocumentStore.getState().saveDocument(bffClient, 'tenant-1', 'user-1');
    
    expect(authorTopologySpy).toHaveBeenCalledWith('tenant-1', expect.objectContaining({
      design: expect.objectContaining({ designLabel: 'v1' })
    }));
    
    authorTopologySpy.mockRestore();
  });
  
  it('surfaces 409 conflict', async () => {
    const mockDoc = {
      schemaVersion: 1 as const,
      designLabel: 'v1',
      revision: '1',
      sites: [],
      locations: [],
      racks: [],
      deviceTypes: [],
      devices: [],
      cables: [],
      signalClasses: [], zones: []
    };
    
    useDocumentStore.getState().loadDocument(mockDoc);
    
    const authorTopologySpy = vi.spyOn(bffClient, 'authorTopology').mockRejectedValue(new Error('409 Conflict'));
    
    await useDocumentStore.getState().saveDocument(bffClient, 'tenant-1', 'user-1');
    
    expect(useDocumentStore.getState().syncConflict).toBe(true);
    
    authorTopologySpy.mockRestore();
  });

  const sampleDoc: any = {
    schemaVersion: 1,
    designLabel: 'Initial',
    sites: [],
    locations: [],
    racks: [],
    deviceTypes: [],
    devices: [],
    cables: [],
    signalClasses: [], zones: []
  };

  it('loads a document and resets history', () => {
    useDocumentStore.setState({ document: null, history: [], historyIndex: -1 });
    const store = useDocumentStore.getState();
    store.loadDocument(sampleDoc);

    const state = useDocumentStore.getState();
    expect(state.document).toEqual(sampleDoc);
    expect(state.history.length).toBe(1);
    expect(state.historyIndex).toBe(0);
  });

  it('updates document using immer-like updater and pushes to history', () => {
    useDocumentStore.setState({ document: null, history: [], historyIndex: -1 });
    useDocumentStore.getState().loadDocument(sampleDoc);

    useDocumentStore.getState().updateDocument((draft: any) => {
      draft.designLabel = 'Updated';
    });

    const state = useDocumentStore.getState();
    expect(state.document?.designLabel).toBe('Updated');
    expect(state.history.length).toBe(2);
    expect(state.historyIndex).toBe(1);
    expect(state.history[0]?.designLabel).toBe('Initial');
    expect(state.history[1]?.designLabel).toBe('Updated');
  });

  it('undoes and redoes changes', () => {
    useDocumentStore.setState({ document: null, history: [], historyIndex: -1 });
    useDocumentStore.getState().loadDocument(sampleDoc);

    useDocumentStore.getState().updateDocument((draft: any) => {
      draft.designLabel = 'Updated';
    });

    useDocumentStore.getState().undo();

    let state = useDocumentStore.getState();
    expect(state.document?.designLabel).toBe('Initial');
    expect(state.historyIndex).toBe(0);

    useDocumentStore.getState().redo();

    state = useDocumentStore.getState();
    expect(state.document?.designLabel).toBe('Updated');
    expect(state.historyIndex).toBe(1);
  });

  it('truncates forward history when updating after undo', () => {
    useDocumentStore.setState({ document: null, history: [], historyIndex: -1 });
    useDocumentStore.getState().loadDocument(sampleDoc);

    useDocumentStore.getState().updateDocument((draft: any) => {
      draft.designLabel = 'Updated 1';
    });

    useDocumentStore.getState().updateDocument((draft: any) => {
      draft.designLabel = 'Updated 2';
    });

    useDocumentStore.getState().undo();

    useDocumentStore.getState().updateDocument((draft: any) => {
      draft.designLabel = 'Forked';
    });

    const state = useDocumentStore.getState();
    expect(state.document?.designLabel).toBe('Forked');
    expect(state.history.length).toBe(3);
    expect(state.historyIndex).toBe(2);
    expect(state.history[2]?.designLabel).toBe('Forked');
  });
});

import { create } from 'zustand';
import { produce } from 'immer';
import type { DesignDocument } from '../model/schema';


export interface StoreApiClient {
  authorTopology: (namespace: string, payload: unknown) => Promise<void>;
  promoteTopology: (namespace: string, targetStatus: string, expectedVersion: string) => Promise<{ revision: string }>;
}

export interface DocumentState {
  document: DesignDocument | null;
  history: DesignDocument[];
  historyIndex: number;
  selectedIds: string[];
  isSaving: boolean;
  syncConflict: boolean;
  remoteFindings: any[];
  setRemoteFindings: (findings: any[]) => void;
  loadDocument: (doc: DesignDocument) => void;
  updateDocument: (updater: (draft: DesignDocument) => void) => void;
  undo: () => void;
  redo: () => void;
  saveDocument: (client: StoreApiClient, namespace: string, actor: string) => Promise<void>;
  resolveConflict: (doc: DesignDocument) => void;
  promoteDocument: (client: StoreApiClient, namespace: string, targetStatus: string) => Promise<void>;
  setSelectedIds: (ids: string[]) => void;
}

export const useDocumentStore = create<DocumentState>((set, get) => ({
  document: null,
  history: [],
  historyIndex: -1,
  selectedIds: [],
  isSaving: false,
  syncConflict: false,
  remoteFindings: [],

  setRemoteFindings: (findings) => set({ remoteFindings: findings }),

  loadDocument: (doc) => set({
    document: doc,
    history: [doc],
    historyIndex: 0,
    selectedIds: [],
    syncConflict: false
  }),

  updateDocument: (updater) => set((state) => {
    if (!state.document) return state;
    const nextDoc = produce(state.document, updater);
    const nextHistory = state.history.slice(0, state.historyIndex + 1);
    nextHistory.push(nextDoc);
    return {
      document: nextDoc,
      history: nextHistory,
      historyIndex: nextHistory.length - 1
    };
  }),

  undo: () => set((state) => {
    if (state.historyIndex > 0) {
      const nextIndex = state.historyIndex - 1;
      return { document: state.history[nextIndex]!, historyIndex: nextIndex };
    }
    return state;
  }),

  redo: () => set((state) => {
    if (state.historyIndex < state.history.length - 1) {
      const nextIndex = state.historyIndex + 1;
      return { document: state.history[nextIndex]!, historyIndex: nextIndex };
    }
    return state;
  }),

  saveDocument: async (client: StoreApiClient, namespace: string, actor: string) => {
    const { document } = get();
    if (!document) return;

    set({ isSaving: true, syncConflict: false });
    try {
      const payload = {
        design: {
          designLabel: document.designLabel,
          revision: document.revision,
          status: 'planned',
          actor,
          expected_version: document.revision
        },
        sites: document.sites,
        locations: document.locations,
        racks: document.racks,
        deviceTypes: document.deviceTypes,
        devices: document.devices,
        cables: document.cables,
        signalClasses: document.signalClasses
      };

      await client.authorTopology(namespace, payload);
      set({ isSaving: false });
    } catch (e: any) {
      if (e.message && e.message.includes('409')) { // Version conflict
        set({ isSaving: false, syncConflict: true });
      } else {
        set({ isSaving: false });
        throw e;
      }
    }
  },

  promoteDocument: async (client: StoreApiClient, namespace: string, targetStatus: string) => {
    const { document } = get();
    if (!document) return;

    set({ isSaving: true, syncConflict: false, remoteFindings: [] });
    try {
      // B105: Run local validators first (simulated via remote findings here if any local fail)
      // and call NCE's system_design_validate_design_graph mock.
      const mockNceValidation = async () => {
        // Mock a failure if document has some problem, e.g. a node called "Fail"
        if (document.devices.some(d => d.name === 'Fail')) {
          return { findings: [{ severity: 'ERROR', message: 'NCE: Node name "Fail" is invalid', source: 'NCE' }] };
        }
        return { findings: [] };
      };

      const valRes = await mockNceValidation();
      if (valRes.findings.length > 0) {
        set({ remoteFindings: valRes.findings, isSaving: false });
        return; // Block promotion
      }

      const res = await client.promoteTopology(namespace, targetStatus, document.revision || '');
      set((state) => {
        if (!state.document) return state;
        const nextDoc = produce(state.document, draft => {
          // B17: revision bumping on active state
          draft.revision = res.revision;
        });
        const nextHistory = state.history.slice(0, state.historyIndex + 1);
        nextHistory.push(nextDoc);
        return {
          document: nextDoc,
          history: nextHistory,
          historyIndex: nextHistory.length - 1,
          isSaving: false
        };
      });
    } catch (e: any) {
      if (e.message && e.message.includes('409')) {
        set({ isSaving: false, syncConflict: true });
      } else {
        set({ isSaving: false });
        throw e;
      }
    }
  },

  setSelectedIds: (ids) => set({ selectedIds: ids }),
  resolveConflict: (doc) => set({
    document: doc,
    history: [doc],
    historyIndex: 0,
    selectedIds: [],
    syncConflict: false
  })
}));

import { useMemo } from 'react';
import { useDocumentStore } from '../documentStore';

export interface BOMItem {
  deviceTypeId: string;
  name: string;
  manufacturer: string;
  quantity: number;
  unitPrice?: number;
}

export function useBOM(): BOMItem[] {
  const document = useDocumentStore(state => state.document);

  return useMemo(() => {
    if (!document) return [];

    const countMap = new Map<string, number>();
    for (const dev of document.devices) {
      countMap.set(dev.deviceTypeId, (countMap.get(dev.deviceTypeId) || 0) + 1);
    }

    const bom: BOMItem[] = [];
    for (const [typeId, qty] of countMap.entries()) {
      const dt = document.deviceTypes.find(d => d.id === typeId);
      if (dt) {
        bom.push({
          deviceTypeId: typeId,
          name: dt.name as string,
          manufacturer: dt.manufacturer as string,
          quantity: qty,
          unitPrice: (dt.pricing as any)?.msrp
        });
      }
    }

    return bom.sort((a, b) => b.quantity - a.quantity);
  }, [document]);
}

export interface CableScheduleRow {
  edgeId: string;
  cableId: string;
  sourceDev: string;
  sourcePort: string;
  targetDev: string;
  targetPort: string;
  lengthM: number;
  type: string;
  signal: string;
}

export function useCableScheduleRows(): CableScheduleRow[] {
  const document = useDocumentStore(state => state.document);

  return useMemo(() => {
    if (!document) return [];

    const deviceMap = new Map(document.devices.map(d => [d.id, d.name ?? d.id]));

    return document.cables.map((e: any) => ({
      edgeId: e.id,
      cableId: e.id.substring(0, 8),
      sourceDev: deviceMap.get(e.terminations[0].deviceId) || e.terminations[0].deviceId,
      sourcePort: e.terminations[0].portRef.name,
      targetDev: deviceMap.get(e.terminations[1].deviceId) || e.terminations[1].deviceId,
      targetPort: e.terminations[1].portRef.name,
      lengthM: e.lengthMeters ?? 10, // will be overridden by B109
      type: e.type,
      signal: e.signalType
    }));
  }, [document]);
}

// B103 Reference Designators live derivations
export function useReferenceDesignators(): Record<string, string> {
  const document = useDocumentStore(state => state.document);
  return useMemo(() => {
    if (!document) return {};
    const designators: Record<string, string> = {};
    const typeCount: Record<string, number> = {};

    for (const dev of document.devices) {
      const dt = document.deviceTypes.find(d => d.id === dev.deviceTypeId);
      const prefix = (dt?.name as string | undefined)?.substring(0, 2).toUpperCase() || 'DV';
      typeCount[prefix] = (typeCount[prefix] || 0) + 1;
      designators[dev.id] = `${prefix}-${typeCount[prefix].toString().padStart(2, '0')}`;
    }
    return designators;
  }, [document]);
}

