import { DesignDocument } from '../model/schema';
import { PortSignature } from '../model/connector-accepts';

export function getPortSignature(document: DesignDocument, deviceId: string, portId: string): PortSignature | null {
  const device = document.devices.find((d: any) => d.id === deviceId);
  if (!device) return null;

  let foundPort: any = null;
  const arrays = [device.interfaces, device.frontPorts, device.rearPorts, device.consolePorts, device.powerPorts, device.powerOutlets];

  for (const arr of arrays) {
    if (!arr) continue;
    for (const p of arr) {
      if (p.id === portId || (p.id == null && portId.endsWith('-' + p.name))) {
        foundPort = p;
        break;
      }
    }
    if (foundPort) break;
  }

  if (!foundPort) return null;

  let signalType = 'UNKNOWN';
  const connectorType = foundPort.type || 'Unknown';

  const ext = (device as any).customFields?.ports;
  if (ext && ext[foundPort.name]?.signal_class) {
    signalType = ext[foundPort.name].signal_class;
  } else {
    const t = connectorType.toLowerCase();
    if (t.includes('1000base') || t.includes('10gbase') || t.includes('rj-45') || t.includes('rj45')) {
      signalType = 'NETWORK';
    } else if (t.includes('hdmi') || t.includes('sdi') || t.includes('displayport')) {
      signalType = 'VIDEO';
    } else if (t.includes('xlr') || t.includes('trs') || t.includes('ts') || t.includes('speakon')) {
      signalType = 'AUDIO';
    } else if (t.includes('iec') || t.includes('nema') || t.includes('power')) {
      signalType = 'POWER';
    }
  }

  return { signalType: signalType as any, connectorType };
}

import { Device, DeviceType, Cable } from '../model/schema';
import { analyseChain, buildChainInput, AdapterInput, nearestIndex } from '@copper/acoustics';

export interface AudioEdgeData {
  status: string;
  dropPercent: number;
  minLoad: number;
  cableImpedanceRe: number;
  voltageAtLoad: number;
}

export interface AudioLineResult {
  valid: boolean;
  errors: string[];
  warnings: string[];
  findings: Array<{
    nodeSlug: string;
    message: string;
    severity: 'Error' | 'Warning' | 'OK';
    voltageAtLoad?: number;
    dropPercent?: number;
    minLoad?: number;
  }>;
  edgeData: Record<string, AudioEdgeData>;
}

export function validateAudioLines(
  devices: Device[],
  deviceTypes: DeviceType[],
  cables: Cable[],
  tempC: number = 20
): AudioLineResult {
  const result: AudioLineResult = {
    valid: true,
    errors: [],
    warnings: [],
    findings: [],
    edgeData: {}
  };

  const input: AdapterInput = {
    devices: devices as any,
    deviceTypes: deviceTypes as any,
    cables: cables as any,
    tempC
  };

  let chainInput;
  try {
    chainInput = buildChainInput(input);
  } catch (err: any) {
    result.valid = false;
    result.errors.push('Failed to build audio signal chain: ' + err.message);
    return result;
  }

  if (chainInput.roots.length === 0) {
    return result;
  }

  const analysis = analyseChain(chainInput);
  const idx1k = nearestIndex(chainInput.grid, 1000);

  // Map cables back to nodes to get edge data
  for (const c of cables) {
    // Assuming t[1] is the downstream target device (speaker)
    const targetId = c.terminations[1]?.deviceId;
    if (targetId) {
      const nodeAnalysis = analysis.get(targetId);
      if (nodeAnalysis) {
        result.edgeData[c.id] = {
          status: nodeAnalysis.results.status,
          dropPercent: nodeAnalysis.results.dropPercent ?? 0,
          minLoad: nodeAnalysis.results.minLoad ?? 0,
          voltageAtLoad: nodeAnalysis.results.voltageAtLoad ?? 0,
          cableImpedanceRe: nodeAnalysis.branch.cableImpedance[idx1k]?.re ?? 0
        };
      }
    }
  }

  for (const [slug, nodeAnalysis] of analysis.entries()) {
    const res = nodeAnalysis.results;
    if (res.status === 'Error' || res.status === 'Warning') {
      const finding: any = {
        nodeSlug: slug,
        message: res.status === 'Error' ? 'Critical audio line fault' : 'Audio line warning',
        severity: res.status
      };
      if (res.voltageAtLoad !== undefined) finding.voltageAtLoad = res.voltageAtLoad;
      if (res.dropPercent !== undefined) finding.dropPercent = res.dropPercent;
      if (res.minLoad !== undefined) finding.minLoad = res.minLoad;
      result.findings.push(finding);

      const msgs = [];
      if (res.dropPercent !== undefined && res.dropPercent > chainInput.quality.maxDrop) {
        msgs.push(`${res.dropPercent.toFixed(1)}% voltage drop`);
      }

      const msgStr = `Node ${slug}: ${msgs.join(', ')}`;
      if (res.status === 'Error') {
        result.valid = false;
        result.errors.push(msgStr);
      } else {
        result.warnings.push(msgStr);
      }
    }
  }

  return result;
}


export function suggestCablesForEdge(cableId: string, devices: Device[], deviceTypes: DeviceType[], cables: Cable[]): DeviceType[] {
  const catalogCables = deviceTypes.filter(dt => dt.customFields?.acoustics?.device_class === "cable");
  const suggestions: DeviceType[] = [];
  for (const candidate of catalogCables) {
    const testCables = cables.map(c => c.id === cableId ? { ...c, type: candidate.id } : c);
    const analysis = validateAudioLines(devices, deviceTypes, testCables);
    const edge = analysis.edgeData[cableId];
    if (edge && edge.status !== "Error") { suggestions.push(candidate); }
  }
  return suggestions;
}


export function suggestAmpsForNode(nodeId: string, devices: Device[], deviceTypes: DeviceType[], cables: Cable[]): DeviceType[] {
  const catalogAmps = deviceTypes.filter(dt => dt.customFields?.acoustics?.device_class === "amplifier");
  const suggestions: DeviceType[] = [];
  for (const candidate of catalogAmps) {
    const testDevices = devices.map(d => d.id === nodeId ? { ...d, deviceTypeId: candidate.id } : d);
    const analysis = validateAudioLines(testDevices, deviceTypes, cables);
    const finding = analysis.findings.find(f => f.nodeSlug === nodeId && f.severity === "Error");
    if (!finding) { suggestions.push(candidate); }
  }
  return suggestions;
}

import { calculateFOV } from '@copper/av-physics';
import { DesignDocument } from '../model/schema';
import { ValidationFinding } from './registry';

export function validateCameraCoverage(doc: DesignDocument): { findings: Omit<ValidationFinding, 'source'>[] } {
  const findings: Omit<ValidationFinding, 'source'>[] = [];

  if (!doc.zones || doc.zones.length === 0) return { findings };

  const getZoneRect = (zoneId: string) => {
    const geo = doc.geometry?.[zoneId];
    if (geo && geo.position && geo.size) {
      return {
        x: geo.position.x * 0.01,
        y: geo.position.y * 0.01,
        width: geo.size.width * 0.01,
        height: geo.size.height * 0.01,
      };
    }
    return null;
  };

  const participantZones = doc.zones.filter(z => z.type === 'participant');

  const cameras = doc.devices.filter(() => true); // We'll filter properly inside

  for (const device of cameras) {
    const type = doc.deviceTypes.find(t => t.id === device.deviceTypeId);
    const camExt = (device as any).customFields?.camera || (type as any)?.customFields?.camera;
    if (!camExt || !camExt.sensor_size || !camExt.focal_min) continue;

    const fov = calculateFOV(camExt.sensor_size, camExt.focal_min);

    const devGeo = doc.geometry?.[device.id]?.position;
    if (!devGeo) continue;
    const devX = devGeo.x * 0.01;
    const devY = devGeo.y * 0.01;

    for (const zone of participantZones) {
      if (zone.locationId && zone.locationId !== device.locationId) continue;
      const zRect = getZoneRect(zone.id);
      if (!zRect) continue;

      const dist = Math.hypot(zRect.x + zRect.width/2 - devX, zRect.y + zRect.height/2 - devY);
      const zoneWidthAngle = 2 * Math.atan((zRect.width / 2) / dist) * (180 / Math.PI);

      if (zoneWidthAngle > fov) {
        findings.push({
          targetId: device.id,
          severity: 'Warning',
          message: `Camera FOV (${fov.toFixed(1)}┬░) cannot cover the entire width of ${zone.name} (${zoneWidthAngle.toFixed(1)}┬░ required).`
        });
      }
    }
  }

  return { findings };
}

import { calculateBDMMaxDistance, calculateISCR } from '@copper/av-physics';
import { DesignDocument } from '../model/schema';
import { ValidationFinding } from './registry';

export function validateDisplaySightlines(doc: DesignDocument): { findings: Omit<ValidationFinding, 'source'>[] } {
  const findings: Omit<ValidationFinding, 'source'>[] = [];

  if (!doc.zones || doc.zones.length === 0) return { findings };

  const getZoneRect = (zoneId: string) => {
    const geo = doc.geometry?.[zoneId];
    if (geo && geo.position && geo.size) {
      return {
        x: geo.position.x * 0.01,
        y: geo.position.y * 0.01,
        width: geo.size.width * 0.01,
        height: geo.size.height * 0.01,
      };
    }
    return null;
  };

  const viewerZones = doc.zones.filter(z => z.type === 'viewer' || z.type === 'participant');

  const displays = doc.devices.filter(() => true);

  for (const device of displays) {
    const type = doc.deviceTypes.find(t => t.id === device.deviceTypeId);
    const displayExt = (device as any).customFields?.display || (type as any)?.customFields?.display;
    if (!displayExt || !displayExt.diagonal) continue;

    const diagMeters = displayExt.diagonal * 0.0254;
    const heightMeters = diagMeters * (9 / Math.sqrt(337));

    const maxDist = calculateBDMMaxDistance(heightMeters);

    const devGeo = doc.geometry?.[device.id]?.position;
    if (!devGeo) continue;
    const devX = devGeo.x * 0.01;
    const devY = devGeo.y * 0.01;

    for (const zone of viewerZones) {
      if (zone.locationId && zone.locationId !== device.locationId) continue;

      const zRect = getZoneRect(zone.id);
      if (!zRect) continue;

      const dists = [
        Math.hypot(zRect.x - devX, zRect.y - devY),
        Math.hypot(zRect.x + zRect.width - devX, zRect.y - devY),
        Math.hypot(zRect.x - devX, zRect.y + zRect.height - devY),
        Math.hypot(zRect.x + zRect.width - devX, zRect.y + zRect.height - devY),
      ];
      const maxZoneDist = Math.max(...dists);

      if (maxZoneDist > maxDist) {
        findings.push({
          targetId: device.id,
          severity: 'Warning',
          message: `Zone ${zone.name} exceeds DISCAS max viewing distance (${maxZoneDist.toFixed(1)}m > ${maxDist.toFixed(1)}m).`
        });
      }
    }

    const ambientLux = 150; 
    const nits = displayExt.nits || 300;
    const blackLevel = nits / 1000;
    const iscr = calculateISCR(nits, blackLevel, ambientLux);
    if (iscr < 15) {
      findings.push({
        targetId: device.id,
        severity: 'Warning',
        message: `ISCR is too low (${iscr.toFixed(1)}:1) for ambient light of ${ambientLux} lux.`
      });
    }
  }

  return { findings };
}

import { DesignDocument } from '../model/schema';
import { ValidationFinding } from './registry';

export function validateLighting(doc: DesignDocument): { findings: Omit<ValidationFinding, 'source'>[] } {
  const findings: Omit<ValidationFinding, 'source'>[] = [];

  if (!doc.zones || doc.zones.length === 0) return { findings };


  const luminaires = doc.devices.filter(() => true);

  for (const device of luminaires) {
    const type = doc.deviceTypes.find(t => t.id === device.deviceTypeId);
    const lightExt = (device as any).customFields?.luminaire || (type as any)?.customFields?.luminaire;
    if (!lightExt || !lightExt.lumens) continue;

    if (lightExt.cri && lightExt.cri < 80) {
      findings.push({
        targetId: device.id,
        severity: 'Warning',
        message: `CRI (${lightExt.cri}) is below recommended 80 for VC/task lighting.`
      });
    }

    const d = 2.5;
    const lux = (lightExt.lumens / (2 * Math.PI * (1 - Math.cos((lightExt.beam_angle || 90) * Math.PI / 360)))) / (d * d);

    if (lux < 300) {
      findings.push({
        targetId: device.id,
        severity: 'Warning',
        message: `Estimated illuminance (${lux.toFixed(0)} lux) is below 300 lux target for task areas.`
      });
    }
  }

  return { findings };
}

import { calculateCriticalDistance, calculatePAGNAGMargin } from '@copper/av-physics';
import { rt60 as calculateRT60, RoomGeometry } from '@copper/acoustics';
import { DesignDocument } from '../model/schema';
import { ValidationFinding } from './registry';

export function validateMicCoverage(doc: DesignDocument): { findings: Omit<ValidationFinding, 'source'>[] } {
  const findings: Omit<ValidationFinding, 'source'>[] = [];

  if (!doc.zones || doc.zones.length === 0) return { findings };


  const mics = doc.devices.filter(() => true);

  for (const device of mics) {
    const type = doc.deviceTypes.find(t => t.id === device.deviceTypeId);
    const micExt = (device as any).customFields?.microphone || (type as any)?.customFields?.microphone;
    if (!micExt || !micExt.polar_pattern) continue;

    const loc = doc.locations.find(l => l.id === device.locationId);
    if (!loc) continue;

    const vol = (loc as any).volume || 100;
    const roomMock: RoomGeometry = { depth: 10, frontWidth: 10, rearWidth: 10, floorFrontZ: 0, floorRearZ: 0, ceilingFrontZ: 3, ceilingRearZ: 3, absorption: 0.1 };
    const roomRt60 = calculateRT60(roomMock);
    const dc = calculateCriticalDistance(vol, roomRt60, 1.5);

    const D0 = 2.0; 
    const Ds = 0.5; 
    const D1 = 3.0; 
    const D2 = 2.0; 

    const margin = calculatePAGNAGMargin(Ds, D0, D1, D2, 1);
    if (margin < 6) {
      findings.push({
        targetId: device.id,
        severity: 'Warning',
        message: `PAG/NAG margin is too low (${margin.toFixed(1)}dB). Risk of acoustic feedback.`
      });
    }

    if (dc < Ds) {
      findings.push({
        targetId: device.id,
        severity: 'Warning',
        message: `Mic is placed beyond critical distance (${Ds}m > ${dc.toFixed(2)}m). Speech intelligibility will be poor.`
      });
    }
  }

  return { findings };
}

