import { useEffect, useRef, CSSProperties } from 'react';
import { Graph } from '@antv/x6';
import { register, getProvider } from '@antv/x6-react-shape';
import { DeviceNodeComponent } from './nodes/DeviceNode';
import { LegendNodeComponent } from './nodes/LegendNode';
import { useDocumentStore } from '../../store/documentStore';

register({
  shape: 'device-node',
  width: 200,
  height: 100,
  component: DeviceNodeComponent,
});

register({
  shape: 'legend-node',
  width: 300,
  height: 250,
  component: LegendNodeComponent,
});

const ReactShapeProvider = getProvider();

export interface CanvasViewProps {
  nodes?: any[];
  edges?: any[];
  className?: string;
  style?: CSSProperties;
  enableWiring?: boolean;
}

import { getPortSignature } from '../../utils/portSignature';
import { canConnect } from '../../model/connector-accepts';
import { useState } from 'react';

const defaultCanvasStyle: CSSProperties = {
  width: '100%',
  height: '100%',
  minHeight: '400px',
  position: 'relative'
};

export function CanvasView({
  nodes = [],
  edges = [],
  style,
  enableWiring = false,
}: CanvasViewProps) {
  const setSelectedIds = useDocumentStore(state => state.setSelectedIds);
  const updateDocument = useDocumentStore(state => state.updateDocument);
  const document = useDocumentStore(state => state.document);
  const containerRef = useRef<HTMLDivElement>(null);
  const graphRef = useRef<Graph | null>(null);

  const [rejectedDrop, setRejectedDrop] = useState<{ srcDevice: string; tgtDevice: string; srcPortType: string; tgtPortType: string; suggestedAdapters: string[] } | null>(null);

  useEffect(() => {
    if (!containerRef.current) return;

    const graph = new Graph({
      container: containerRef.current,
      autoResize: true,
      background: { color: 'var(--md-sys-color-surface-container-lowest)' },
      panning: true,
      mousewheel: { enabled: true, modifiers: ['ctrl', 'meta'] },
      interacting: { nodeMovable: enableWiring, edgeMovable: enableWiring },
      connecting: {
        router: {
          name: 'normal',
        },
        connector: { name: 'rounded', args: { radius: 8 } },
        allowBlank: false,
        allowLoop: false,
        allowNode: false,
        validateConnection({ sourceMagnet, targetMagnet, sourceCell, targetCell }) {
          if (!sourceMagnet || !targetMagnet) return false;
          if (sourceCell === targetCell) return false;
          const srcPortGroup = sourceMagnet.getAttribute('port-group');
          const tgtPortGroup = targetMagnet.getAttribute('port-group');
          if (srcPortGroup === tgtPortGroup) return false; // Prevent in->in or out->out

          // Additional logic for B102: Check connector/signal class compatibility
          // For now just prevent same-group wiring. Full check happens at drop.
          return true;
        }
      }
    });

    graphRef.current = graph;

    return () => {
      graph.dispose();
    };
  }, [enableWiring]);

  useEffect(() => {
    const graph = graphRef.current;
    if (!graph) return;

    const x6Nodes = nodes.map(n => ({
      ...n,
      ports: {
        ...n.ports,
        groups: {
          in: {
            position: 'absolute',
            attrs: {
              circle: { r: 4, magnet: true, stroke: 'var(--md-sys-color-outline)', fill: 'var(--md-sys-color-surface)', strokeWidth: 1 }
            }
          },
          out: {
            position: 'absolute',
            attrs: {
              circle: { r: 4, magnet: true, stroke: 'var(--md-sys-color-outline)', fill: 'var(--md-sys-color-surface)', strokeWidth: 1 }
            }
          }
        }
      }
    }));

    const x6Edges = edges.map(e => ({
      ...e,
      tools: ['vertices', 'segments'],
      attrs: {
        line: {
          stroke: 'var(--md-sys-color-outline)',
          strokeWidth: 2,
          targetMarker: { name: 'block', width: 6, height: 6 }
        }
      }
    }));

    graph.fromJSON({ nodes: x6Nodes, edges: x6Edges });
    graph.centerContent();

    graph.on('cell:click', ({ cell }) => {
      setSelectedIds([cell.id]);
    });

    graph.on('blank:click', () => {
      setSelectedIds([]);
    });

    graph.on('edge:connected', ({ isNew, edge }: any) => {
      if (!isNew || !document) return;
      const source = edge.getSource();
      const target = edge.getTarget();

      if (source.cell && target.cell && source.port && target.port) {
        // B102: Connect Assist Validation
        const srcSig = getPortSignature(document, source.cell, source.port);
        const tgtSig = getPortSignature(document, target.cell, target.port);

        if (srcSig && tgtSig && !canConnect(srcSig, tgtSig)) {
          // Reject
          edge.remove();

          // Suggest adapters (naive mock for Dante etc)
          const suggestedAdapters: string[] = [];
          if (srcSig.signalType === 'AUDIO' && tgtSig.signalType === 'NETWORK') {
            suggestedAdapters.push('Dante AVIO Adapter');
          } else if (srcSig.signalType === 'VIDEO' && tgtSig.signalType === 'NETWORK') {
            suggestedAdapters.push('SDVoE Encoder');
          }

          setRejectedDrop({
            srcDevice: document.devices.find(d => d.id === source.cell)?.name || source.cell,
            tgtDevice: document.devices.find(d => d.id === target.cell)?.name || target.cell,
            srcPortType: srcSig.connectorType,
            tgtPortType: tgtSig.connectorType,
            suggestedAdapters
          });
          return;
        }

        updateDocument(draft => {
          draft.cables.push({
            id: edge.id,
            terminations: [
              { deviceId: source.cell, portRef: { name: source.port.split('-').pop() || source.port, kind: source.port.split('-')[0] || 'interface' } as any },
              { deviceId: target.cell, portRef: { name: target.port.split('-').pop() || target.port, kind: target.port.split('-')[0] || 'interface' } as any }
            ],
            type: 'cat6',
            signalType: srcSig?.signalType || 'ETHERNET',
            status: 'planned'
          });
        });
      }
    });

  }, [nodes, edges, setSelectedIds, document, updateDocument]);

  return (
    <div className="copper-canvas-container" style={{ ...defaultCanvasStyle, ...style }} data-testid="copper-canvas-view">
      <div ref={containerRef} style={{ width: '100%', height: '100%' }} />
      <ReactShapeProvider />
      {rejectedDrop && (
        <div style={{
          position: 'absolute', top: '50%', left: '50%', transform: 'translate(-50%, -50%)',
          background: 'var(--copper-surface-container-high)', border: '1px solid var(--copper-outline)', padding: 24, borderRadius: 12,
          boxShadow: 'var(--md-sys-elevation-level-4)', zIndex: 10000, color: 'var(--copper-on-surface)'
        }}>
          <h3 style={{ margin: '0 0 16px 0', color: 'var(--copper-error)' }}>Incompatible Connection</h3>
          <p style={{ margin: '0 0 16px 0' }}>
            Cannot connect <b>{rejectedDrop.srcPortType}</b> ({rejectedDrop.srcDevice}) to <b>{rejectedDrop.tgtPortType}</b> ({rejectedDrop.tgtDevice}).
          </p>
          {rejectedDrop.suggestedAdapters.length > 0 && (
            <div style={{ marginBottom: 16 }}>
              <strong style={{ display: 'block', marginBottom: 8 }}>Suggested Adapters:</strong>
              {rejectedDrop.suggestedAdapters.map((a: string, i: number) => (
                <button key={i} style={{ padding: '4px 12px', background: 'var(--copper-primary-container)', color: 'var(--copper-on-primary-container)', border: 'none', borderRadius: 4, marginRight: 8 }}>
                  {a}
                </button>
              ))}
            </div>
          )}
          <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
            <button onClick={() => setRejectedDrop(null)} style={{ padding: '8px 16px', background: 'var(--copper-primary)', color: 'var(--copper-on-primary)', border: 'none', borderRadius: 8, cursor: 'pointer' }}>
              Dismiss
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useMemo } from 'react';
import { useDocumentStore } from '../../store/documentStore';
import { validateAudioLines, suggestAmpsForNode } from '../../validation/audio-line';

export const NodeInspector: React.FC = () => {
  const selectedIds = useDocumentStore(state => state.selectedIds);
  const document = useDocumentStore(state => state.document);
  const updateDocument = useDocumentStore(state => state.updateDocument);

  if (!document || selectedIds.length !== 1) return null;

  const selectedId = selectedIds[0];
  const device = document.devices.find(d => d.id === selectedId);

  if (!device) return null;

  const deviceType = document.deviceTypes.find(dt => dt.id === device.deviceTypeId);
  if (!deviceType) return null;

  // B98 Audio Line validation (only applies to amplifiers)
  const isAmp = deviceType.customFields?.acoustics?.device_class === 'amplifier';
  const audioRes = isAmp ? validateAudioLines(document.devices, document.deviceTypes, document.cables) : null;
  const finding = audioRes?.findings.find(f => f.nodeSlug === device.id && f.severity !== 'OK');

  const suggestions = useMemo(() => {
    if (!finding || !isAmp) return [];
    return suggestAmpsForNode(device.id, document.devices, document.deviceTypes, document.cables);
  }, [finding, isAmp, device.id, document.devices, document.deviceTypes, document.cables]);

  // B104 Capability Alternatives
  const alternatives = useMemo(() => {
    if (!deviceType.customFields?.acoustics) return [];
    const { category, type, impedance } = deviceType.customFields.acoustics;

    return document.deviceTypes
      .filter(dt => 
        dt.id !== deviceType.id &&
        dt.customFields?.acoustics?.category === category &&
        dt.customFields?.acoustics?.type === type &&
        dt.customFields?.acoustics?.impedance === impedance
      )
      .slice(0, 3);
  }, [deviceType, document.deviceTypes]);

  const handleApplyAlternative = (altTypeId: string) => {
    updateDocument(draft => {
      const d = draft.devices.find(x => x.id === device.id);
      if (d) d.deviceTypeId = altTypeId;
    });
  };

  return (
    <div style={{ position: 'absolute', top: 16, right: 16, width: 320, background: 'var(--copper-surface)', border: '1px solid var(--copper-outline)', borderRadius: 8, padding: 16, zIndex: 10 }}>
      <h3 className="m3-title-medium" style={{ margin: '0 0 8px 0' }}>{device.name}</h3>
      <div className="m3-label-medium" style={{ color: 'var(--copper-on-surface-variant)', marginBottom: 16 }}>
        {deviceType.manufacturer} {deviceType.model}
      </div>

      {finding && (
        <div style={{ padding: 12, background: 'var(--copper-error-container)', color: 'var(--copper-on-error-container)', borderRadius: 8, marginBottom: 16 }}>
          <strong>{finding.severity}:</strong> {finding.message}
          {suggestions.length > 0 && (
            <div style={{ marginTop: 8 }}>
              <div className="m3-label-small">Suggested fixes:</div>
              {suggestions.map(s => (
                <button
                  key={s.suggestedAmpId as string}
                  onClick={() => handleApplyAlternative(s.suggestedAmpId as string)}
                  className="m3-button m3-button-filled m3-button-small"
                  style={{ display: 'block', marginTop: 4, width: '100%' }}
                >
                  Swap to {document.deviceTypes.find(d => d.id === s.suggestedAmpId)?.model}
                </button>
              ))}
            </div>
          )}
        </div>
      )}

      {alternatives.length > 0 && (
        <div style={{ marginTop: 16 }}>
          <h4 className="m3-label-medium" style={{ marginBottom: 8 }}>Alternatives by Capability</h4>
          {alternatives.map((alt: any) => (
            <div key={alt.id as string} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', background: 'var(--copper-surface-container)', padding: '8px 12px', borderRadius: 4, marginBottom: 4 }}>
              <span className="m3-body-small">{alt.manufacturer} {alt.model}</span>
              <button 
                onClick={() => handleApplyAlternative(alt.id as string)}
                className="m3-button m3-button-text"
                style={{ padding: '0 8px', minWidth: 'auto', height: 24, fontSize: '0.75rem' }}
              >
                Swap
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

import { useState } from 'react';
import { useDocumentStore } from '../../store/documentStore';

export function CableRoutingMode() {
  const document = useDocumentStore(state => state.document);
  const updateDocument = useDocumentStore(state => state.updateDocument);
  const [computing, setComputing] = useState(false);

  if (!document) return null;

  const handleComputeRoutes = async () => {
    setComputing(true);
    try {
      // B109: Map floorplan geometry to routing nodes
      const nodes = document.devices
        .filter(d => document.geometry?.[d.id]?.position)
        .map(d => {
          const pos = document.geometry![d.id].position;
          return {
            id: d.id,
            x: pos.x,
            y: pos.y,
            width: 32,
            height: 32
          };
        });

      // Filter only cables between devices placed on the floorplan
      const validDeviceIds = new Set(nodes.map(n => n.id));
      const edges = document.cables
        .filter(c => 
          c.terminations.length === 2 && 
          validDeviceIds.has(c.terminations[0].deviceId) && 
          validDeviceIds.has(c.terminations[1].deviceId)
        )
        .map(c => ({
          id: c.id,
          source: c.terminations[0].deviceId,
          target: c.terminations[1].deviceId
        }));

      if (nodes.length === 0 || edges.length === 0) {
        alert('Place devices on the floorplan and connect them first.');
        setComputing(false);
        return;
      }

      const worker = new Worker(new URL('../../router/worker.ts', import.meta.url), { type: 'module' });
      worker.postMessage({ nodes, edges, bounds: [] });
      worker.onmessage = (e) => {
        const res = e.data;
        updateDocument(draft => {
          edges.forEach((e, idx) => {
            const path = res.bestPaths[idx];
            if (!path) return;
            const points = path.split('L').map((s: string) => s.replace('M', '').trim().split(' ').map(Number));
            let length = 0;
            for (let i = 1; i < points.length; i++) {
              const [x1, y1] = points[i-1];
              const [x2, y2] = points[i];
              if (!isNaN(x1) && !isNaN(y1) && !isNaN(x2) && !isNaN(y2)) {
                length += Math.sqrt(Math.pow(x2-x1, 2) + Math.pow(y2-y1, 2));
              }
            }
            const lengthMeters = Math.max(1, Math.round(length * 0.01 * 10) / 10);

            const cable = draft.cables.find(c => c.id === e.id);
            if (cable) {
              cable.length = lengthMeters;
              if (!draft.geometry) draft.geometry = {};
              if (!draft.geometry.routes) draft.geometry.routes = {};
              draft.geometry.routes[cable.id] = path;
            }
          });
        });
        setComputing(false);
        worker.terminate();
      };
      worker.onerror = (e) => {
        console.error('Routing worker failed', e);
        setComputing(false);
        worker.terminate();
      };
    } catch (e) {
      setComputing(false);
    }
  };

  const routes = document.geometry?.routes || {};

  return (
    <div style={{ position: 'relative', width: '100%', height: '100%', overflow: 'auto', background: 'var(--copper-surface-container-lowest)' }}>
      {/* Locations */}
      {document.locations.map(loc => {
        const layout = (loc as any).layout || { x: 0, y: 0, width: 400, height: 300 };
        return (
          <div
            key={loc.id}
            style={{ position: 'absolute', left: layout.x, top: layout.y, width: layout.width, height: layout.height, border: '2px solid var(--copper-outline)', background: 'var(--copper-surface-container)', opacity: 0.3 }}
          />
        );
      })}

      {/* Routes SVG */}
      <svg style={{ position: 'absolute', top: 0, left: 0, width: '100%', height: '100%', pointerEvents: 'none', zIndex: 5 }}>
        {Object.entries(routes).map(([cableId, path]) => (
          <path key={cableId} d={path as string} fill="none" stroke="var(--copper-primary)" strokeWidth="2" strokeDasharray="4 2" />
        ))}
      </svg>

      {/* Devices Layer */}
      {document.devices.map(device => {
        const pos = document.geometry?.[device.id]?.position;
        if (!pos) return null;
        return (
          <div key={device.id} style={{ position: 'absolute', left: pos.x, top: pos.y, width: 24, height: 24, transform: 'translate(-50%, -50%)', background: 'var(--copper-secondary)', borderRadius: '50%', zIndex: 10 }} />
        );
      })}

      <div style={{ position: 'absolute', top: 16, right: 16, zIndex: 20 }}>
        <button 
          className="m3-button m3-button-filled"
          onClick={handleComputeRoutes}
          disabled={computing}
        >
          {computing ? 'Routing...' : 'Compute Cable Routes'}
        </button>
      </div>
    </div>
  );
}

import { useParams, useNavigate } from 'react-router-dom';
import { ConnectedCanvasView } from '../../shell/index';
import { SceneView } from '../scene/SceneView';
import { FloorplanMode } from './FloorplanMode';
import { CableRoutingMode } from './CableRoutingMode';
import { useDocumentStore } from '../../store/documentStore';
import { ProblemsPanel } from '../../ui/problems/ProblemsPanel';
import { exportToDxf } from '../../export/dxf';

export function DesignWorkspace() {
  const { mode } = useParams();
  const navigate = useNavigate();
  const document = useDocumentStore(state => state.document);

  const currentMode = mode || 'schematic';

  const handleExportDXF = () => {
    if (!document) return;
    const nodes = document.devices.map((d: any) => ({
      id: d.name || d.id,
      position: { x: d.geometry?.x ?? 0, y: d.geometry?.y ?? 0 },
      initialWidth: 200,
      initialHeight: 100
    }));
    const edges = document.cables.map((c: any) => ({
      source: document.devices.find((d: any) => d.id === c.terminations[0].deviceId)?.name || c.terminations[0].deviceId,
      target: document.devices.find((d: any) => d.id === c.terminations[1].deviceId)?.name || c.terminations[1].deviceId,
    }));
    const dxfStr = exportToDxf(nodes, edges);
    const blob = new Blob([dxfStr], { type: 'application/dxf' });
    const url = URL.createObjectURL(blob);
    const a = window.document.createElement('a');
    a.href = url;
    a.download = 'design.dxf';
    a.click();
  };

  const modes = [
    { id: 'schematic', label: 'Schematic' },
    { id: 'floorplan', label: 'Floorplan' },
    { id: 'routing', label: 'Cable Routing' },
    { id: '3d', label: '3D Scene' }
  ];

  if (!document) {
    return <div className="m3-content-padding">Loading document...</div>;
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh', width: '100vw', overflow: 'hidden' }}>
      <div style={{ display: 'flex', justifyContent: 'center', padding: '8px', background: 'var(--copper-surface-container)', borderBottom: '1px solid var(--copper-outline-variant)' }}>
        <div style={{ display: 'flex', background: 'var(--copper-surface)', borderRadius: 8, overflow: 'hidden', border: '1px solid var(--copper-outline)' }}>
          {modes.map((m, idx) => {
            const isActive = currentMode === m.id;
            return (
              <button
                key={m.id}
                onClick={() => navigate('/design/' + m.id)}
                style={{
                  padding: '8px 16px',
