import React, { useState, useRef } from 'react';
import { useDocumentStore } from '../../store/documentStore';

function DraggableDevice({ device, geometry, updateGeometry }: { device: any, geometry: any, updateGeometry: (id: string, pos: {x: number, y: number}) => void }) {
  const [isDragging, setIsDragging] = useState(false);
  const pos = geometry?.position || { x: 0, y: 0 };
  const ref = useRef<HTMLDivElement>(null);

  const handlePointerDown = (e: React.PointerEvent) => {
    e.stopPropagation();
    e.currentTarget.setPointerCapture(e.pointerId);
    setIsDragging(true);
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!isDragging) return;
    e.stopPropagation();
    const newX = pos.x + e.movementX;
    const newY = pos.y + e.movementY;
    updateGeometry(device.id, { x: newX, y: newY });
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    e.stopPropagation();
    e.currentTarget.releasePointerCapture(e.pointerId);
    setIsDragging(false);
  };

  return (
    <div
      ref={ref}
      title={device.name}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
      onPointerCancel={handlePointerUp}
      style={{
        position: 'absolute',
        left: pos.x,
        top: pos.y,
        width: 32,
        height: 32,
        transform: 'translate(-50%, -50%)',
        background: 'var(--copper-primary)',
        color: 'var(--copper-on-primary)',
        borderRadius: '50%',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        cursor: isDragging ? 'grabbing' : 'grab',
        userSelect: 'none',
        boxShadow: 'var(--md-sys-elevation-level-1)',
        zIndex: isDragging ? 10 : 1,
        fontSize: '0.75rem',
        fontWeight: 'bold'
      }}
    >
      {device.name?.substring(0, 2) || 'D'}
    </div>
  );
}

export function FloorplanMode() {
  const document = useDocumentStore(state => state.document);
  const updateDocument = useDocumentStore(state => state.updateDocument);

  if (!document) return null;

  const handleUpdateGeometry = (deviceId: string, position: {x: number, y: number}) => {
    updateDocument((draft: any) => {
      if (!draft.geometry) draft.geometry = {};
      if (!draft.geometry[deviceId]) draft.geometry[deviceId] = {};
      draft.geometry[deviceId].position = position;
    });
  };

  const locations = document.locations || [];
  const devices = document.devices || [];

  return (
    <div style={{ position: 'relative', width: '100%', height: '100%', overflow: 'auto', background: 'var(--copper-surface-container-lowest)' }}>
      {/* Rooms Layer */}
      {locations.map(loc => {
        const layout = (loc as any).layout || { x: 0, y: 0, width: 400, height: 300 };
        return (
          <div
            key={loc.id}
            style={{
              position: 'absolute',
              left: layout.x,
              top: layout.y,
              width: layout.width,
              height: layout.height,
              border: '2px solid var(--copper-outline)',
              background: 'var(--copper-surface-container)',
              opacity: 0.8
            }}
          >
            <div style={{ padding: '8px', fontWeight: 'bold', color: 'var(--copper-on-surface)', userSelect: 'none' }}>
              {loc.name || loc.id}
            </div>
          </div>
        );
      })}

      {/* Devices Layer */}
      {devices.map(device => (
        <DraggableDevice
          key={device.id}
          device={device}
          geometry={document.geometry?.[device.id]}
          updateGeometry={handleUpdateGeometry}
        />
      ))}
    </div>
  );
}

import { useState, useMemo } from 'react';
import { useDocumentStore } from '../../store/documentStore';

export function DevicePalette() {
  const [searchTerm, setSearchTerm] = useState('');
  const document = useDocumentStore((state) => state.document);
  const updateDocument = useDocumentStore((state) => state.updateDocument);

  const deviceTypes = document?.deviceTypes || [];

  const filteredTypes = useMemo(() => {
    if (!searchTerm.trim()) return deviceTypes;

    const search = searchTerm.toLowerCase();
    const terms = search.split(/\s+/).filter(Boolean);

    return deviceTypes.filter((dt) => {
      const searchSpace = [
        dt.manufacturer,
        dt.model,
        dt.id,
        dt.description,
        dt.customFields?.acoustics?.category,
        dt.customFields?.acoustics?.type,
        dt.customFields?.acoustics?.impedance ? String(dt.customFields.acoustics.impedance) + 'Ohm ' + String(dt.customFields.acoustics.impedance) + 'O' : '',
        dt.customFields?.acoustics?.wattage_rms ? String(dt.customFields.acoustics.wattage_rms) + 'W' : ''
      ].filter(Boolean).join(' ').toLowerCase();

      return terms.every(term => searchSpace.includes(term));
    });
  }, [deviceTypes, searchTerm]);

  const handleAddDevice = (deviceTypeId: string) => {
    updateDocument((draft) => {
      const siteId = draft.sites?.[0]?.id || 'default-site';
      const dt = (draft.deviceTypes || []).find(d => d.id === deviceTypeId);

      const baseName = dt ? (dt.model || deviceTypeId) : deviceTypeId;
      const newId = 'dev-' + Math.random().toString(36).substring(2, 9);

      draft.devices.push({
        id: newId,
        deviceTypeId,
        siteId,
        status: 'planned',
        name: baseName + ' (New)'
      });
    });
  };

  if (!document) {
    return <div data-testid="device-palette-empty">No document loaded</div>;
  }

  return (
    <div style={{ width: 280, borderRight: '1px solid var(--md-sys-color-outline-variant)', background: 'var(--md-sys-color-surface)', display: 'flex', flexDirection: 'column', zIndex: 10 }}>
      <div style={{ padding: 16, borderBottom: '1px solid var(--md-sys-color-outline-variant)' }}>
        <h3 className="m3-title-medium" style={{ margin: '0 0 16px 0' }}>Device Palette</h3>
        <input 
          type="text"
          className="m3-text-field"
          style={{ width: '100%', padding: '8px 12px', borderRadius: 4, border: '1px solid var(--md-sys-color-outline)' }}
          placeholder="Search (e.g. '8O 200W ceiling')"
          value={searchTerm}
          onChange={e => setSearchTerm(e.target.value)}
        />
      </div>

      <div style={{ flex: 1, overflowY: 'auto', padding: 8 }}>
        <p className="m3-label-small" style={{ margin: '0 8px 8px 8px', color: 'var(--md-sys-color-on-surface-variant)' }}>
          {filteredTypes.length} types found
        </p>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
          {filteredTypes.map(dt => (
            <div 
              key={dt.id}
              onClick={() => handleAddDevice(dt.id)}
              style={{
                padding: 12,
                borderRadius: 8,
                background: 'var(--md-sys-color-surface-container-low)',
                cursor: 'pointer',
                border: '1px solid transparent'
              }}
              onMouseEnter={e => e.currentTarget.style.border = '1px solid var(--md-sys-color-primary)'}
              onMouseLeave={e => e.currentTarget.style.border = '1px solid transparent'}
            >
              <div className="m3-label-medium" style={{ fontWeight: 600 }}>{dt.manufacturer} {dt.model}</div>
              <div className="m3-body-small" style={{ color: 'var(--md-sys-color-on-surface-variant)', marginTop: 4 }}>
                {dt.customFields?.acoustics?.type ? String(dt.customFields.acoustics.type) + ' ' : ''}
                {dt.customFields?.acoustics?.category ? String(dt.customFields.acoustics.category) + ' ' : ''}
                {dt.customFields?.acoustics?.wattage_rms ? String(dt.customFields.acoustics.wattage_rms) + 'W ' : ''}
                {dt.customFields?.acoustics?.impedance ? String(dt.customFields.acoustics.impedance) + '╬® ' : ''}
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

import type { EquipmentDatabase, SignalNode } from './types/domain';
import type { ChainInput } from './engine';

export interface CopperDeviceType {
  id: string;
  manufacturer: string;
  model: string;
  slug: string;
  customFields?: {
    acoustics?: any;
  };
}

export interface CopperDevice {
  id: string;
  name?: string;
  deviceTypeId: string;
  interfaces?: { id: string; name: string }[];
  frontPorts?: { id: string; name: string }[];
  rearPorts?: { id: string; name: string }[];
  customFields?: {
    acoustics?: any;
  };
}

export interface CopperCable {
  type?: string;
  id: string;
  terminations: [
    { deviceId: string; portRef: { kind: string; id?: string; name: string } },
    { deviceId: string; portRef: { kind: string; id?: string; name: string } }
  ];
  lengthM?: number;
  customFields?: {
    acoustics?: any;
  };
}

export interface AdapterInput {
  deviceTypes: CopperDeviceType[];
  devices: CopperDevice[];
  cables: CopperCable[];
  tempC?: number;
}

export function buildChainInput(input: AdapterInput): ChainInput {
  const db: EquipmentDatabase = {
    speakers: {},
    cables: {},
    amplifiers: {}
  };

  const ampRack: Record<string, { slug: string; modelId: string; channelsUsed: number[] }> = {};

  for (const dt of input.deviceTypes) {
    const ac = dt.customFields?.acoustics;
    if (!ac) continue;

    if (ac.device_class === 'speaker') {
      db.speakers[dt.id] = {
        slug: dt.slug,
        manufacturer: dt.manufacturer,
        model: dt.model,
        impedance: ac.impedance ?? 8,
        z_min: ac.z_min,
        wattage_rms: ac.wattage_rms ?? 0,
        wattage_peak: ac.wattage_peak,
        max_spl: ac.max_spl,
        taps: ac.taps ?? [],
        type: ac.type as any,
        category: ac.category
      };
    } else if (ac.device_class === 'amplifier') {
      db.amplifiers[dt.id] = {
        slug: dt.slug,
        manufacturer: dt.manufacturer,
        model: dt.model,
        min_load: ac.min_load,
        watt_8: ac.watt_8,
        watt_4: ac.watt_4,
        watt_2: ac.watt_2,
        watt_100v: ac.watt_100v,
        min_load_bridge: ac.min_load_bridge,
        watt_bridge_8: ac.watt_bridge_8,
        watt_bridge_4: ac.watt_bridge_4
      };
    } else if (ac.device_class === 'cable') {
      db.cables[dt.id] = {
        slug: dt.slug,
        manufacturer: dt.manufacturer,
        model: dt.model,
        resistance: ac.resistance ?? 0,
        capacitance: ac.capacitance,
        inductance: ac.inductance
      };
    }
  }

  for (const c of input.cables) {
    const ac = c.customFields?.acoustics;
    if (ac && ac.device_class === 'cable') {
      db.cables[c.id] = {
        slug: c.id,
        manufacturer: 'Custom',
        model: 'Cable',
        resistance: ac.resistance ?? 0,
        capacitance: ac.capacitance,
        inductance: ac.inductance
      };
    }
  }

  const deviceMap = new Map<string, CopperDevice>();
  for (const d of input.devices) {
    deviceMap.set(d.id, d);
    if (db.amplifiers[d.deviceTypeId]) {
      ampRack[d.id] = { slug: d.name || d.id, modelId: d.deviceTypeId, channelsUsed: [] };
    }
  }

  const connectionsByDevice = new Map<string, { cable: CopperCable, otherDevice: string, otherPort: string, myPort: string }[]>();
  for (const c of input.cables) {
    const t0 = c.terminations[0];
    const t1 = c.terminations[1];
    if (!connectionsByDevice.has(t0.deviceId)) connectionsByDevice.set(t0.deviceId, []);
    if (!connectionsByDevice.has(t1.deviceId)) connectionsByDevice.set(t1.deviceId, []);
    connectionsByDevice.get(t0.deviceId)!.push({ cable: c, otherDevice: t1.deviceId, otherPort: t1.portRef.name, myPort: t0.portRef.name });
    connectionsByDevice.get(t1.deviceId)!.push({ cable: c, otherDevice: t0.deviceId, otherPort: t0.portRef.name, myPort: t1.portRef.name });
  }

  const roots: SignalNode[] = [];
  const visitedNodes = new Set<string>();

  function buildTree(deviceId: string, cableFromParent: CopperCable | null, parentId: string | null, ampInstanceId: string): SignalNode | null {
    if (visitedNodes.has(deviceId)) return null;
    const dev = deviceMap.get(deviceId);
    if (!dev) return null;
    const isAmp = !!db.amplifiers[dev.deviceTypeId];
    const isSpeaker = !!db.speakers[dev.deviceTypeId];
    if (!isAmp && !isSpeaker) return null;
    visitedNodes.add(deviceId);
    let cableType = (cableFromParent?.type && db.cables[cableFromParent.type]) ? cableFromParent.type : (cableFromParent?.customFields?.acoustics?.device_class === 'cable' ? cableFromParent.id : undefined);
    if (!cableType && cableFromParent) {
      const dbCableKeys = Object.keys(db.cables);
      if (dbCableKeys.length > 0) cableType = dbCableKeys[0];
    }
    const node: SignalNode = {
      slug: dev.id,
      parentId: parentId,
      userLabel: dev.name || dev.id,
      ampInstanceId: ampInstanceId,
      ampChannel: 1,
      useBridgeMode: false,
      speakerId: isSpeaker ? dev.deviceTypeId : '',
      parallelCount: 1,
      tapPower: dev.customFields?.acoustics?.taps?.[0] || 0,
      cableId: cableType || '',
      length: cableFromParent?.lengthM ?? 0,
      useCable2: false,
      cable2Id: '',
      length2: 0,
      children: [],
      results: { status: 'OK' }
    };
    const conns = connectionsByDevice.get(deviceId) || [];
    for (const conn of conns) {
      if (cableFromParent && conn.cable.id === cableFromParent.id) continue;
      const childNode = buildTree(conn.otherDevice, conn.cable, dev.id, ampInstanceId);
      if (childNode) node.children.push(childNode);
    }
    visitedNodes.delete(deviceId);
    return node;
  }

  for (const [id] of deviceMap.entries()) {
    if (ampRack[id]) {
      const conns = connectionsByDevice.get(id) || [];
      for (const conn of conns) {
        if (conn.myPort.toLowerCase().includes('in')) continue;
        const childNode = buildTree(conn.otherDevice, conn.cable, null, id);
        if (childNode) roots.push(childNode);
      }
    }
  }

  let mode: 'low-z' | 'high-v' = 'low-z';
  for (const root of roots) {
    const spk = db.speakers[root.speakerId];
    if (spk && (spk.type === '100V' || spk.type === 'Both' || root.tapPower > 0)) { mode = 'high-v'; break; }
  }

  return { roots, db, ampRack, mode, quality: { name: 'Standard', color: '#000000', minDamping: 20, maxDrop: 10, hfCheckHz: 10000 }, tempC: input.tempC ?? 20, grid: [100, 1000, 10000] };
}

/** High-level physics orchestrator ÔÇö takes a signal-chain tree and produces
 *  per-node spectral results. This replaces the monolithic calculateAll()
 *  god function from the legacy codebase with a pure, testable function.
 *
 *  Design:
 *    - No side effects. Returns a new Map<nodeId, NodeAnalysis>.
 *    - Recursive: handles arbitrary daisy-chain depth.
 *    - Spectral: every result is a function of frequency (array across grid).
 *    - Scalar summaries (minLoad, dropPercent at 1 kHz) are derived from the
 *      spectral data at the end.
 */

import { Complex, parallel } from './complex'
import { cableImpedance, seriesImpedance } from './cable'
import { speakerImpedance } from './driver'
import { reflectedImpedance } from './transformer'
import { transmission, ratioToDb } from './transmission'
import { nearestIndex } from './grid'
import type {
  SignalNode,
  EquipmentDatabase,
  SystemMode,
  QualityProfile,
  NodeResults,
  Speaker,
} from './types/domain'
import type {
  BranchAnalysis,
  FrequencyGrid,
  SpectralImpedance,
  SpectralMagnitude,
} from './types/physics'

export interface ChainInput {
  roots: SignalNode[]
  db: EquipmentDatabase
  ampRack: Record<string, { slug: string; modelId: string; channelsUsed: number[] }>
  mode: SystemMode
  quality: QualityProfile
  tempC: number
  grid: FrequencyGrid
}

export interface NodeAnalysis {
  branch: BranchAnalysis
  results: NodeResults
}

export type ChainAnalysis = Map<string, NodeAnalysis>

const MAX_IMPEDANCE = 1e9

function spkImpedance(spk: Speaker | undefined, parallelCount: number, grid: FrequencyGrid): SpectralImpedance {
  if (!spk) return grid.map(() => new Complex(MAX_IMPEDANCE, 0))
  return speakerImpedance(spk, parallelCount, grid)
}

/** Effective load Z(f) looking into a node ÔÇö recursive parallel sum with
 *  child cable impedances added in series on each branch.
 */
function effectiveLoad(node: SignalNode, db: EquipmentDatabase, tempC: number, grid: FrequencyGrid): SpectralImpedance {
  const spk = db.speakers[node.speakerId]
  const own = spkImpedance(spk, node.parallelCount || 1, grid)
  if (!node.children?.length) return own

  const branches: SpectralImpedance[] = [own]
  for (const child of node.children) {
    const childLoad = effectiveLoad(child, db, tempC, grid)
    const c1 = db.cables[child.cableId]
    let zCab: SpectralImpedance = c1 ? cableImpedance(c1, child.length, tempC, grid) : grid.map(() => Complex.ZERO)
    if (child.useCable2 && child.cable2Id) {
      const c2 = db.cables[child.cable2Id]
      if (c2) zCab = seriesImpedance(zCab, cableImpedance(c2, child.length2, tempC, grid))
    }
    const branchZ = grid.map((_: any, i: number) => childLoad[i]!.add(zCab[i]!))
    branches.push(branchZ)
  }

  // Parallel combine per frequency.
  const out = new Array<Complex>(grid.length)
  for (let i = 0; i < grid.length; i++) {
    out[i] = parallel(branches.map((b) => b[i]!))
  }
  return out
}

function totalTapPower(node: SignalNode): number {
  let w = Number(node.tapPower) || 0
  for (const c of node.children) w += totalTapPower(c)
  return w
}

function totalRmsPower(node: SignalNode, db: EquipmentDatabase): number {
  const spk = db.speakers[node.speakerId]
  let p = spk ? spk.wattage_rms * Math.max(1, node.parallelCount || 1) : 0
  for (const c of node.children) p += totalRmsPower(c, db)
  return p
}

/** Source voltage for a root node based on amplifier config. */
function rootSourceVoltage(node: SignalNode, input: ChainInput): number {
  const { mode, db, ampRack } = input
  if (node.ampInstanceId && ampRack[node.ampInstanceId]) {
    const inst = ampRack[node.ampInstanceId]!
    const m = db.amplifiers[inst.modelId]
    if (m) {
      if (mode === 'high-v') return 100
      const p = node.useBridgeMode ? m.watt_bridge_8 ?? m.watt_8 ?? 0 : m.watt_8 ?? 0
      return Math.sqrt(Math.max(0, p) * 8)
    }
  }
  // Default fallback: 100V for distributed, or ÔêÜ(100W┬À8╬®)=28.28 V for Low-Z.
  return mode === 'high-v' ? 100 : Math.sqrt(100 * 8)
}

/** Evaluate a single node given the voltage presented at its input. */
function analyzeNode(
  node: SignalNode,
  srcVoltage: number,
  input: ChainInput,
): { branch: BranchAnalysis; tipVoltage: SpectralMagnitude } {
  const { db, grid, tempC, mode } = input

  const cable = db.cables[node.cableId]
  let cableZ: SpectralImpedance = cable
    ? cableImpedance(cable, node.length, tempC, grid)
    : grid.map(() => Complex.ZERO)
  if (node.useCable2 && node.cable2Id) {
    const c2 = db.cables[node.cable2Id]
    if (c2) cableZ = seriesImpedance(cableZ, cableImpedance(c2, node.length2, tempC, grid))
  }

  const loadZ: SpectralImpedance =
    mode === 'high-v'
      ? grid.map(() => new Complex(reflectedImpedance(totalTapPower(node), 100), 0))
      : effectiveLoad(node, db, tempC, grid)

  const tx = transmission(srcVoltage, loadZ, cableZ, grid)

  const branch: BranchAnalysis = {
    frequencies: grid,
    cableImpedance: cableZ,
    loadImpedance: loadZ,
    transmission: tx,
  }
  return { branch, tipVoltage: tx.voltageAtLoad }
}

/** Judge status against the quality profile. */
function grade(
  results: NodeResults,
  node: SignalNode,
  input: ChainInput,
): NodeResults {
  const { quality, mode, db, ampRack } = input
  const msg: string[] = []
  let status: NodeResults['status'] = 'OK'

  if ((results.dropPercent ?? 0) > quality.maxDrop) {
    status = 'Warning'
    msg.push('High drop')
  }
  if ((results.dropPercent ?? 0) > quality.maxDrop * 1.5) {
    status = 'Error'
    msg[msg.length - 1] = 'Critical drop'
  }
  if (Math.abs(results.hfLossDb ?? 0) > 0.5 && status !== 'Error') {
    status = 'Warning'
    msg.push('HF loss')
  }

  // Amp headroom (only meaningful on root nodes with an assigned amp).
  if (!node.parentId && node.ampInstanceId && ampRack[node.ampInstanceId]) {
    const inst = ampRack[node.ampInstanceId]!
    const amp = db.amplifiers[inst.modelId]
    if (amp) {
      const totalLoad = results.minLoad ?? 8
      let cap = 0
      if (mode === 'low-z') {
        if (node.useBridgeMode) {
          cap = totalLoad < 6 ? amp.watt_bridge_4 ?? 0 : amp.watt_bridge_8 ?? 0
          if (cap === 0 && amp.watt_bridge_8) cap = amp.watt_bridge_8
        } else {
          if (totalLoad < 3) cap = amp.watt_2 ?? 0
          else if (totalLoad < 6) cap = amp.watt_4 ?? 0
          else cap = amp.watt_8 ?? 0
          if (cap === 0) cap = amp.watt_4 ?? amp.watt_8 ?? 0
        }
        const required = totalRmsPower(node, db)
        results.headroomPct = cap > 0 ? (required / cap) * 100 : 0
      } else {
        cap = amp.watt_100v ?? amp.watt_8 ?? 0
        results.headroomPct = cap > 0 ? ((results.totalPower ?? 0) / cap) * 100 : 0
      }
      if ((results.headroomPct ?? 0) > 80) {
        status = status === 'Error' ? 'Error' : 'Warning'
        msg.push(`Headroom ${Math.round(results.headroomPct!)}%`)
      }
      if ((results.headroomPct ?? 0) > 100) {
        status = 'Error'
        msg[msg.length - 1] = `Overload ${Math.round(results.headroomPct!)}%`
      }
    }
  }

  if (amplifierOverloaded(node, results, input)) {
    status = 'Error'
    msg.push('Amp min load')
  }

  return { ...results, status, ...(msg.length > 0 ? { statusMessage: msg.join(' | ') } : {}) }
}

function amplifierOverloaded(node: SignalNode, results: NodeResults, input: ChainInput): boolean {
  if (node.parentId || !node.ampInstanceId) return false
  const inst = input.ampRack[node.ampInstanceId]
  if (!inst) return false
  const amp = input.db.amplifiers[inst.modelId]
  if (!amp) return false
  const minLoad = node.useBridgeMode ? amp.min_load_bridge ?? amp.min_load ?? 2 : amp.min_load ?? 2
  return (results.minLoad ?? 8) < minLoad
}

/** Main entry point ÔÇö analyse the whole chain and return per-node results. */
export function analyseChain(input: ChainInput): ChainAnalysis {
  const out: ChainAnalysis = new Map()

  const walk = (node: SignalNode, parentVoltage: SpectralMagnitude | null): void => {
    let srcV: number
    if (!node.parentId || parentVoltage === null) {
      srcV = rootSourceVoltage(node, input)
    } else {
      const idx = nearestIndex(input.grid, 1000)
      srcV = parentVoltage[idx]!
    }
    const { branch, tipVoltage } = analyzeNode(node, srcV, input)
    const scalar = deriveScalar(branch, input, srcV)
    if (input.mode === 'high-v') scalar.totalPower = totalTapPower(node)
    const graded = grade(scalar, node, input)
    out.set(node.slug, { branch, results: graded })
    for (const child of node.children) walk(child, tipVoltage)
  }

  for (const root of input.roots) walk(root, null)
  return out
}

function deriveScalar(branch: BranchAnalysis, input: ChainInput, srcV: number): NodeResults {
  const idx1k = nearestIndex(input.grid, 1000)
  const idxHf = nearestIndex(input.grid, input.quality.hfCheckHz)
  const { transmission: tx, cableImpedance: cz, loadImpedance: lz } = branch
  const vLoad = tx.voltageAtLoad[idx1k]!
  return {
    status: 'OK',
    minLoad: lz[idx1k]!.magnitude() + cz[idx1k]!.re,
    nomLoad: lz[idx1k]!.magnitude() + cz[idx1k]!.re,
    dropPercent: tx.dropPercent[idx1k]!,
    dropVolts: srcV - vLoad,
    voltageAtLoad: vLoad,
    current: tx.current[idx1k]!,
    hfLossDb: ratioToDb(vLoad, tx.voltageAtLoad[idxHf]!),
    elecLossDb: ratioToDb(srcV, vLoad),
  }
}

import * as fs from 'node:fs';
import * as path from 'node:path';
import { fileURLToPath } from 'node:url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const ROOT = path.resolve(__dirname, '..');
const CSV_DIR = path.join(ROOT, '..', 'Speaker Design Tool v2.0', 'public', 'csv');
const OUT_DIR = path.join(ROOT, 'catalog', 'audio');

function slugify(text: string) {
  return text.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
}

function writeYaml(manufacturer: string, model: string, extraData: any, type: string) {
  const mfrSlug = slugify(manufacturer);
  const modelSlug = slugify(model);
  const outPath = path.join(OUT_DIR, mfrSlug);
  if (!fs.existsSync(outPath)) {
    fs.mkdirSync(outPath, { recursive: true });
  }
  const slug = mfrSlug + '-' + modelSlug;
  let yaml = '---\nmanufacturer: "' + manufacturer + '"\nmodel: "' + model + '"\nslug: "' + slug + '"\nu_height: 1\nis_full_depth: false\n';
  yaml += 'copper_extensions:\n  acoustics:\n    device_class: "' + type + '"\n';
  for (const [k, v] of Object.entries(extraData)) {
    if (v !== '' && v !== undefined) {
      if (Array.isArray(v)) {
        yaml += '    ' + k + ': [' + v.join(', ') + ']\n';
      } else if (!isNaN(Number(v))) {
        yaml += '    ' + k + ': ' + v + '\n';
      } else {
        yaml += '    ' + k + ': "' + v + '"\n';
      }
    }
  }
  fs.writeFileSync(path.join(outPath, modelSlug + '.yaml'), yaml);
}

function run() {
  let countSpk = 0; let countAmp = 0; let countCab = 0;

  const spkTxt = fs.readFileSync(path.join(CSV_DIR, 'speakers_db_v2.csv'), 'utf8');
  const spkLines = spkTxt.split('\n').map(l => l.trim()).filter(l => l);
  for (let i = 1; i < spkLines.length; i++) {
    const row = spkLines[i].split(',').map(c => c.trim());
    if (row.length < 2) continue;
    const model = row[0]; const brand = row[1];
    const impedance = row[2]; const z_min = row[3];
    const wattage_rms = row[4]; const wattage_peak = row[5];
    const max_spl = row[6];
    const category = row.pop();
    const type = row.pop();
    const taps = row.slice(7).filter(t => t);
    writeYaml(brand, model, { impedance, z_min, wattage_rms, wattage_peak, max_spl, taps, type, category }, 'speaker');
    countSpk++;
  }

  const ampTxt = fs.readFileSync(path.join(CSV_DIR, 'amplifiers_db_v2.csv'), 'utf8');
  const ampLines = ampTxt.split('\n').map(l => l.trim()).filter(l => l);
  for (let i = 1; i < ampLines.length; i++) {
    const row = ampLines[i].split(',').map(c => c.trim());
    if (row.length < 2) continue;
    const model = row[0]; const brand = row[1];
    const df = row[2]; const df_rated_at = row[3];
    const min_load = row[4]; const watt_8 = row[5];
    const watt_4 = row[6]; const watt_2 = row[7];
    const watt_100v = row[8]; const min_load_bridge = row[9];
    const watt_bridge_8 = row[10]; const watt_bridge_4 = row[11];
    const max_voltage_peak = row[12];
    writeYaml(brand, model, { df, df_rated_at, min_load, watt_8, watt_4, watt_2, watt_100v, min_load_bridge, watt_bridge_8, watt_bridge_4, max_voltage_peak }, 'amplifier');
    countAmp++;
  }

  const cabTxt = fs.readFileSync(path.join(CSV_DIR, 'cables_db_v2.csv'), 'utf8');
  const cabLines = cabTxt.split('\n').map(l => l.trim()).filter(l => l);
  for (let i = 1; i < cabLines.length; i++) {
    const row = cabLines[i].split(',').map(c => c.trim());
    if (row.length < 2) continue;
    const name = row[0]; const brand = row[1]; const model = row[2] || name;
    const resistance = row[3]; const capacitance = row[4]; const inductance = row[5];
    writeYaml(brand, model, { resistance, capacitance, inductance }, 'cable');
    countCab++;
  }

  console.log('Parsed ' + countSpk + ' speakers, ' + countAmp + ' amps, ' + countCab + ' cables.');
}

run();
